import itertools

def check_condition(A):
    for x, y, z in itertools.combinations(A, 3):
        if (x + y + z) % 2 == 0:
            # a, b, c = (x-y+z)//2, (x+y-z)//2, (-x+y+z)//2
            # Only need to check the smallest one: (x+y-z)//2 >= 1
            if x + y - z >= 2:
                return True
    return False

def max_subset_size(N):
    # Brute force is too slow. Let's use a more efficient search.
    # For a fixed N, we want to find the largest subset that DOES NOT satisfy the condition.
    # This is like finding the maximum independent set in some hypergraph.
    # Let's try a simple backtracking search.
    best_size = 0
    def backtrack(current_set, candidate_start):
        nonlocal best_size
        if len(current_set) > best_size:
            best_size = len(current_set)

        for i in range(candidate_start, N + 1):
            # Check if adding i violates the condition with any two elements in current_set
            possible = True
            for x, y in itertools.combinations(current_set, 2):
                # New element is z, and z > y > x
                if (x + y + i) % 2 == 0 and x + y - i >= 2:
                    possible = False
                    break
            if possible:
                backtrack(current_set + [i], i + 1)

    backtrack([], 1)
    return best_size

