import itertools

def check_condition_abc_in_A(A):
    # A is a sorted list of integers
    # We need to find a, b, c in A such that a+b, b+c, c+a are also in A
    for a, b, c in itertools.combinations(A, 3):
        x, y, z = a + b, b + c, c + a
        if x in A and y in A and z in A:
            return True
    return False

def max_subset_size_abc_in_A(N):
    import itertools
    max_size = 0
    for r in range(1, N + 1):
        for A in itertools.combinations(range(1, N + 1), r):
            if not check_condition_abc_in_A(A):
                max_size = max(max_size, r)
    return max_size

for N in range(5, 15):
    print(f"N={N}, max_size={max_subset_size_abc_in_A(N)}")
